const retrieveKBPassages = `-- name: RetrieveKBPassages :many
SELECT
    c.id,
    c.document_id,
    c.source_id,
    s.name AS source_name,
    d.rel_path,
    c.heading_path,
    c.content,
    c.locator,
    (1 - (c.embedding <=> $1))::float8 AS score
FROM kb_chunks c
JOIN kb_documents d ON d.id = c.document_id
JOIN kb_sources s ON s.id = c.source_id
WHERE c.embedding IS NOT NULL
  AND c.generation = d.generation
  AND c.embedding_model = $2::text
  AND d.generation > 0
  AND s.enabled
  AND (c.scope = 'shared' OR (c.scope = 'user' AND c.owner_id = $3::bigint))
  AND (d.scope = 'shared' OR (d.scope = 'user' AND d.owner_id = $3::bigint))
  AND d.scope = c.scope
  AND d.owner_id IS NOT DISTINCT FROM c.owner_id
  AND d.source_id = c.source_id
  AND s.scope = c.scope
  AND s.owner_id IS NOT DISTINCT FROM c.owner_id
  AND ($4::bigint IS NULL OR c.source_id = $4::bigint)
  AND ($5::text IS NULL OR starts_with(d.rel_path, $5::text))
ORDER BY c.embedding <=> $1, c.id
LIMIT $6::int
`

type RetrieveKBPassagesParams struct {
	Embedding      pgvector.Vector
	EmbeddingModel string
	OwnerID        int64
	SourceID       pgtype.Int8
	PathPrefix     pgtype.Text
	LimitCount     int32
}

type RetrieveKBPassagesRow struct {
	ID          int64
	DocumentID  int64
	SourceID    int64
	SourceName  string
	RelPath     string
	HeadingPath []string
	Content     string
	Locator     []byte
	Score       float64
}

func (q *Queries) RetrieveKBPassages(ctx context.Context, arg RetrieveKBPassagesParams) ([]RetrieveKBPassagesRow, error) {
	rows, err := q.db.Query(ctx, retrieveKBPassages,
		arg.Embedding,
		arg.EmbeddingModel,
		arg.OwnerID,
		arg.SourceID,
		arg.PathPrefix,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RetrieveKBPassagesRow{}
	for rows.Next() {
		var i RetrieveKBPassagesRow
		if err := rows.Scan(
			&i.ID,
			&i.DocumentID,
			&i.SourceID,
			&i.SourceName,
			&i.RelPath,
			&i.HeadingPath,
			&i.Content,
			&i.Locator,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

